		public MatterTest setHandler(Handler handler) {
			this.handler = handler;
			LOGGER.addHandler(handler); // assign so the LOGGER can only output results to the Handler
			return this;
		}

		/**
		 * Returns a new populated Matter
		 * 
		 * @return Matter
		 */
		protected Matter generateNewEntity() {
			Matter entity = new Matter( null,  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  org.apache.commons.lang3.RandomStringUtils.randomAlphanumeric(16),  new HashSet<>(),  null,  new HashSet<>(),  new HashSet<>(),  MatterType.values()[0],  MatterStatus.values()[0] );
			
			return( entity );
		}

